class TestTimetable():
  def setup_method(self, method):
    self.driver = webdriver.Chrome()
    self.vars = {}
  
  def teardown_method(self, method):
    self.driver.quit()
  
  def test_timetable(self):
    self.driver.get("http://localhost:5173/login")
    self.driver.maximize_window()

    # 1. Wait for login form and submit administrator credentials
    WebDriverWait(self.driver, 10).until(
        expected_conditions.presence_of_element_located((By.NAME, "email"))
    )
    self.driver.find_element(By.NAME, "email").send_keys("melbin@gmail.com")
    self.driver.find_element(By.NAME, "password").send_keys("123456")
    self.driver.find_element(By.XPATH, "//button[@type='submit']").click()

    # 2. Wait for redirect to administrator dashboard
    WebDriverWait(self.driver, 10).until(
        expected_conditions.url_contains("/administrator")
    )

    # 3. Navigate to Timetable Generator
    self.driver.get("http://localhost:5173/administrator/timetable")

    # 4. Wait for Generate button and click it
    gen_btn = WebDriverWait(self.driver, 10).until(
        expected_conditions.element_to_be_clickable(
            (By.XPATH, "//button[contains(., 'Generate') or contains(., 'Timetable')]")
        )
    )
    gen_btn.click()

    # 5. Wait for the timetable schedule matrix to appear
    WebDriverWait(self.driver, 10).until(
        expected_conditions.presence_of_element_located(
            (By.XPATH, "//*[contains(text(), 'Monday')]")
        )
    )

    # 6. Assert timetable generated successfully
    assert len(self.driver.find_elements(By.XPATH, "//*[contains(text(), 'Monday')]")) > 0
    print("\n✅ TIMETABLE TEST PASSED! Weekly timetable generated successfully.")

if __name__ == "__main__":
    pytest.main(["test_timetablee.py", "-v", "-s"])
